<script setup>
import { computed, ref } from 'vue'
import { CalendarDays, Check, CreditCard, Download, MoreHorizontal, Pencil, Plus, ReceiptText, Search, Trash2, WalletCards, X } from 'lucide-vue-next'
import { confirmPayment, createPaymentMethod, deleteUnusedPaymentMethod, savePaymentMethod, store } from '../demo-store'

const tab = ref('payments')
const query = ref('')
const methodModal = ref(false)
const activeMethod = ref(null)
const methodForm = ref({ name: '', type: 'Virtual account', provider: 'Midtrans', fee: 'Sesuai kontrak' })
const filteredPayments = computed(() => store.payments.filter((payment) => `${payment.id} ${payment.student} ${payment.channel}`.toLowerCase().includes(query.value.toLowerCase())))
const filteredMethods = computed(() => store.paymentMethods.filter((method) => `${method.name} ${method.type} ${method.provider}`.toLowerCase().includes(query.value.toLowerCase())))
function statusClass(value) { return value === 'Terbayar' || value === 'Aktif' ? 'status-terbit' : value === 'Menunggu' ? 'status-review' : 'status-arsip' }
function openMethod(method = null) { activeMethod.value = method; methodForm.value = method ? { name: method.name, type: method.type, provider: method.provider, fee: method.fee } : { name: '', type: 'Virtual account', provider: 'Midtrans', fee: 'Sesuai kontrak' }; methodModal.value = true }
async function saveMethod() {
  if (!methodForm.value.name.trim()) return
  try {
    if (activeMethod.value) await savePaymentMethod(activeMethod.value, methodForm.value)
    else await createPaymentMethod(methodForm.value)
    methodModal.value = false
  } catch (error) { window.alert(error.message) }
}
async function toggleMethod(method) {
  try { await savePaymentMethod(method, { isActive: method.status !== 'Aktif' }) }
  catch (error) { window.alert(error.message) }
}
async function removeMethod(method) {
  if (method.usage > 0) { window.alert('Metode ini memiliki riwayat transaksi. Nonaktifkan agar transaksi lama tetap dapat dibaca.'); return }
  if (!window.confirm(`Hapus metode ${method.name}?`)) return
  try { await deleteUnusedPaymentMethod(method) }
  catch (error) { window.alert(error.message) }
}
</script>

<template>
  <div class="view-wrap">
    <div class="page-title-row"><div><div class="eyebrow">PENDAPATAN <span>/</span> FINANCE</div><h1>Langganan & pembayaran</h1><p class="page-subtitle">Kelola transaksi, metode pembayaran, dan paket akses murid.</p></div><button v-if="tab === 'methods'" class="button button-primary" @click="openMethod()"><Plus :size="17" /> Tambah metode</button><button v-else-if="tab === 'plans'" class="button button-primary"><Plus :size="17" /> Buat paket langganan</button><button v-else class="button button-outline"><Download :size="16" /> Ekspor transaksi</button></div>
    <div class="finance-metrics"><div class="finance-metric"><span class="metric-icon green"><WalletCards :size="18" /></span><div><small>Penerimaan terkonfirmasi</small><strong>Rp 38.420.000</strong><em><span class="trend-up">+12,4%</span> bulan ini</em></div></div><div class="finance-metric"><span class="metric-icon lilac"><CreditCard :size="18" /></span><div><small>Langganan aktif</small><strong>1.847</strong><em>pada 3 paket aktif</em></div></div><div class="finance-metric"><span class="metric-icon peach"><ReceiptText :size="18" /></span><div><small>Perlu konfirmasi</small><strong>3 transaksi</strong><em>Menunggu pembayaran</em></div></div></div>
    <div class="content-tabs"><button :class="['content-tab', { active: tab === 'payments' }]" @click="tab = 'payments'">Pembayaran <span>{{ store.payments.length }}</span></button><button :class="['content-tab', { active: tab === 'plans' }]" @click="tab = 'plans'">Paket langganan <span>{{ store.plans.length }}</span></button><button :class="['content-tab', { active: tab === 'methods' }]" @click="tab = 'methods'">Metode pembayaran <span>{{ store.paymentMethods.length }}</span></button></div>
    <template v-if="tab === 'payments'"><div class="filter-row"><label class="search-field"><Search :size="17" /><input v-model="query" placeholder="Cari invoice atau nama murid..." /></label><button class="filter-select"><CalendarDays :size="15" /> 30 hari terakhir</button></div><section class="panel table-panel"><div class="table-scroll"><table class="data-table payment-table"><thead><tr><th>INVOICE</th><th>MURID / PAKET</th><th>METODE</th><th>TANGGAL</th><th>JUMLAH</th><th>STATUS</th><th></th></tr></thead><tbody><tr v-for="payment in filteredPayments" :key="payment.id"><td><b class="invoice-id">{{ payment.id }}</b></td><td><div class="table-primary"><b>{{ payment.student }}</b><small>{{ payment.plan }}</small></div></td><td><span class="payment-channel"><CreditCard :size="15" />{{ payment.channel }}</span></td><td class="muted-cell">{{ payment.date }}</td><td class="amount-cell">{{ payment.amount }}</td><td><span :class="['status-tag', statusClass(payment.status)]"><i></i>{{ payment.status }}</span></td><td><button v-if="payment.status === 'Menunggu'" class="inline-action" @click="confirmPayment(payment)"><Check :size="14" /> Konfirmasi</button><button v-else class="icon-button tiny"><MoreHorizontal :size="16" /></button></td></tr></tbody></table></div><div class="table-footer"><span>Menampilkan {{ filteredPayments.length }} transaksi contoh</span><div class="pagination"><button disabled>‹</button><button class="current-page">1</button><button>2</button><button>›</button></div></div></section><div class="info-callout"><div class="callout-mark">i</div><p><b>Hak akses hanya aktif setelah pembayaran dikonfirmasi.</b> Produksi memakai callback gateway terverifikasi dan idempoten. Demo ini tidak terhubung ke gateway.</p></div></template>
    <template v-else-if="tab === 'plans'"><div class="plan-grid"><article v-for="(plan, index) in store.plans" :key="plan.name" class="panel plan-card"><div class="plan-top"><span :class="['plan-icon', `plan-${index}`]"><WalletCards :size="19" /></span><span class="status-tag status-terbit"><i></i>{{ plan.state }}</span></div><h2>{{ plan.name }}</h2><p>{{ plan.validity }} akses · {{ plan.quota }}</p><strong>{{ plan.price }}</strong><div class="plan-bottom"><span>{{ plan.students }} murid berlangganan</span><button class="icon-button tiny"><MoreHorizontal :size="16" /></button></div></article><button class="add-plan-card"><span><Plus :size="20" /></span><b>Tambah paket</b><small>Atur masa aktif dan kuota baru</small></button></div><div class="info-callout"><div class="callout-mark">i</div><p>Perpanjangan dilakukan manual. Pembatalan mempertahankan akses sampai masa bayar berakhir; refund penuh mencabut akses. Refund parsial tidak tersedia pada MVP.</p></div></template>
    <template v-else><div class="filter-row"><label class="search-field"><Search :size="17" /><input v-model="query" placeholder="Cari nama atau penyedia metode..." /></label><span class="provider-note">Gateway demo: Midtrans · metode tersedia mengikuti konfigurasi merchant</span></div><section class="panel table-panel"><div class="table-scroll"><table class="data-table method-table"><thead><tr><th>METODE</th><th>JENIS</th><th>PENYEDIA</th><th>BIAYA</th><th>TRANSAKSI TERPAKAI</th><th>STATUS</th><th>AKSI</th></tr></thead><tbody><tr v-for="method in filteredMethods" :key="method.id"><td><b class="method-name">{{ method.name }}</b><small class="method-id">{{ method.id }}</small></td><td>{{ method.type }}</td><td>{{ method.provider }}</td><td>{{ method.fee }}</td><td>{{ method.usage.toLocaleString('id-ID') }}</td><td><span :class="['status-tag', statusClass(method.status)]"><i></i>{{ method.status }}</span></td><td><div class="row-actions"><button class="icon-button tiny" title="Edit metode" @click="openMethod(method)"><Pencil :size="14" /></button><button class="icon-button tiny" :title="method.status === 'Aktif' ? 'Nonaktifkan' : 'Aktifkan'" @click="toggleMethod(method)"><CreditCard :size="14" /></button><button class="icon-button tiny danger-icon" title="Hapus metode" :disabled="method.usage > 0" @click="removeMethod(method)"><Trash2 :size="14" /></button></div></td></tr><tr v-if="!filteredMethods.length"><td colspan="7" class="empty-state">Belum ada metode pembayaran.</td></tr></tbody></table></div><div class="table-footer"><span>Metode dengan riwayat transaksi hanya dapat dinonaktifkan.</span><span>{{ filteredMethods.length }} metode</span></div></section><div class="info-callout"><div class="callout-mark">i</div><p>Kelola metode yang disediakan gateway. Secret key tetap disimpan pada konfigurasi server dan tidak ditampilkan di panel.</p></div></template>
    <div v-if="methodModal" class="modal-backdrop" @click.self="methodModal = false"><section class="modal-card form-modal"><button class="modal-close" @click="methodModal = false"><X :size="18" /></button><span class="section-kicker">METODE PEMBAYARAN · {{ activeMethod?.id || 'BARU' }}</span><h2>{{ activeMethod ? 'Edit metode' : 'Tambah metode' }}</h2><p class="modal-description">Daftar metode yang tersedia diaktifkan pada gateway pilihan.</p><label class="field-label">Nama tampilan<input v-model="methodForm.name" placeholder="Contoh: BCA Virtual Account" /></label><label class="field-label">Jenis<select v-model="methodForm.type"><option>Virtual account</option><option>QRIS</option><option>E-wallet</option><option>Kartu</option><option>Transfer bank</option></select></label><label class="field-label">Penyedia gateway<select v-model="methodForm.provider"><option>Midtrans</option><option>Xendit</option><option>Manual</option></select></label><label class="field-label">Informasi biaya<input v-model="methodForm.fee" placeholder="Sesuai kontrak" /></label><div class="modal-footer"><button class="button button-outline" @click="methodModal = false">Batal</button><button class="button button-primary" :disabled="!methodForm.name.trim()" @click="saveMethod">Simpan metode</button></div></section></div>
  </div>
</template>
